arguments.script:
var scene=UnityEngine.SceneManagement.SceneManager.CreateScene("Isolated motor checks",new UnityEngine.SceneManagement.CreateSceneParameters(UnityEngine.SceneManagement.LocalPhysicsMode.Physics2D));var physics=scene.GetPhysicsScene2D();
var host=new UnityEngine.GameObject("Isolated motor rig");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(host,scene);host.SetActive(false);
var prefab=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>("Assets/Prefabs/Character.prefab");var clone=UnityEngine.Object.Instantiate(prefab,host.transform);
foreach(var m in clone.GetComponentsInChildren<UnityEngine.MonoBehaviour>(true))if(!(m is Character.Control.TargetMovement)&&!(m is Character.Control.ArmsSimulation))UnityEngine.Object.DestroyImmediate(m);
host.SetActive(true);var arms=clone.GetComponentInChildren<Character.Control.ArmsSimulation>();var input=clone.GetComponentInChildren<Character.Control.TargetMovement>();input.enabled=false;input.ResetTarget();
var body=clone.transform.Find("Cauldron").GetComponent<UnityEngine.Rigidbody2D>();body.constraints=UnityEngine.RigidbodyConstraints2D.FreezeAll;
foreach(var rb in clone.GetComponentsInChildren<UnityEngine.Rigidbody2D>())rb.gravityScale=0;
void Tick(int n){for(int i=0;i<n;i++){arms.SendMessage("FixedUpdate");physics.Simulate(.02f);}}
try{
var center=clone.transform.Find("Center");
foreach(var t in clone.GetComponentsInChildren<UnityEngine.Transform>())if(t.name.ToLower().Contains("center"))UnityEngine.Debug.Log("center "+t.name+" "+t.position);
var origin=(UnityEngine.Vector2)body.position;
foreach(var dir in new[]{UnityEngine.Vector2.left,UnityEngine.Vector2.up,UnityEngine.Vector2.right}){
float lo,hi;bool ok=arms.TryReachInterval(dir,out lo,out hi);UnityEngine.Debug.Log("interval "+dir+" "+ok+" "+lo+".."+hi);
arms.ReceiveTarget(origin+dir*3);Tick(240);UnityEngine.Debug.Log("after "+dir+" tip="+arms.HammerTip.position+" axis="+clone.GetComponentInChildren<UnityEngine.SliderJoint2D>().transform.right+" angleError="+arms.AngleError+" extension="+arms.ExtensionError);
}
}finally{UnityEngine.Object.DestroyImmediate(host);UnityEngine.SceneManagement.SceneManager.UnloadSceneAsync(scene);}
